$ocrQuota=max(0,(int)setting('wechat.ocr.daily_quota','100'));
$ocrQuotaDay=(new \DateTimeImmutable('now',new \DateTimeZone('Asia/Shanghai')))->format('Y-m-d');
$ocrUsed=0;$ocrCounterReady=true;
try{$ocrUsed=(int)db()->fetchValue("SELECT COUNT(*) FROM ocr_usage_logs WHERE quota_day=:day AND status='success'",['day'=>$ocrQuotaDay]);}catch(\Throwable $e){$ocrCounterReady=false;}
$ocrRemaining=$ocrCounterReady?max(0,$ocrQuota-$ocrUsed):null;
$decodeOcr=function($ciphertext,$context){if(!$ciphertext)return [];try{$plain=decrypt_private_value((string)$ciphertext,$context);$data=json_decode((string)$plain,true);return is_array($data)?$data:[];}catch(\Throwable $e){return [];}};
?>
